                s.frames.add(frame);
            }
        }

        return s;
    }

    // -----------------------------------------------------------------------
    // Helper: find the HeadlessApplication main-loop thread by name
    // -----------------------------------------------------------------------

    private static Thread findHeadlessThread() {
        // Walk all thread groups to locate the "HeadlessApplication" thread
